 1	import java.util.Objects;
 2	
 3	public final class BinarySearch {
 4	    public static final int NOT_FOUND = -1;
 5	
 6	    private BinarySearch() {
 7	    }
 8	
 9	    /**
10	     * Searches an ascending sorted array and returns the target index, or -1 when absent.
11	     */
12	    public static int binarySearch(int[] sortedValues, int target) {
13	        Objects.requireNonNull(sortedValues, "sortedValues");
14	
15	        int left = 0;
16	        int right = sortedValues.length - 1;
17	
18	        while (left <= right) {
19	            int middle = midpoint(left, right);
20	            int value = sortedValues[middle];
21	
22	            if (value == target) {
23	                return middle;
24	            }
25	
26	            if (value < target) {
27	                left = middle + 1;
28	            } else {
29	                right = middle - 1;
30	            }
31	        }
32	
33	        return NOT_FOUND;
34	    }
35	
36	    private static int midpoint(int left, int right) {
37	        return left + (right - left) / 2;
38	    }
39	}
